insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 38, 10, 'Meu coração dá palpitações, e minha força me deixou; e a luz dos meus olhos já não [está] comigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 38, 11, 'Meus amigos e companheiros observam de longe minha calamidade; e os meus vizinhos ficam afastados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 38, 12, 'Os que procuram [matar] a minha alma [me] armam laços; e os que procuram o meu mal falam insultos e todo o dia planejam maldades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 38, 13, 'Mas eu [estou] como o surdo, não ouço; e como o mudo, [que] não abre sua boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 38, 14, 'E eu estou como um homem que não ouve, e cuja boca não [pode responder] com repreensões.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 38, 15, 'Por isso, SENHOR, eu espero em ti; Senhor, meu Deus, tu me ouvirás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 38, 16, 'Porque eu dizia: Não se alegrem de mim!Quando meu pé vacilou, eles se engrandeceram contra mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 38, 17, 'Porque eu estou prestes a ficar como manco, e minha dor está continuamente perante mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 38, 18, 'Por isso eu [te] conto minha maldade; estou aflito por causa do meu pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 38, 19, 'Porém meus inimigos [estão] vivos, [e] se fortalecem; e os que me odeiam por maldade se multiplicam;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 38, 20, 'Assim como os que retribuem o bem com o mal, eles se opõem a mim, porque eu sigo o bem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 38, 21, 'Não me desampares, SENHOR, meu Deus, não fiques longe de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 38, 22, 'Apressa-te ao meu socorro, SENHOR, salvação minha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 39, 1, 'Salmo de Davi, para o regente, conforme “Jedutum”: Eu dizia: Vigiarei os meus caminhos, para eu não pecar com minha língua; vigiarei minha boca com freio, enquanto o perverso ainda estiver em frente a mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 39, 2, 'Eu fiquei calado, nada falei de bom; e minha dor se agravou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 39, 3, 'Meu coração se esquentou dentro de mim, fogo se acendeu em minha meditação; [então] eu disse com minha língua:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 39, 4, 'Conta-me, SENHOR, o meu fim, e a duração dos meus dias, para que eu saiba como eu sou frágil.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 39, 5, 'Eis que a palmos tu ordenaste os meus dias, e o tempo de minha vida [é] como nada diante de ti; pois todo homem que existe [é] um nada. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 39, 6, 'Certamente o homem anda pela aparência, certamente se inquietam em vão; ajuntam [bens] , e não sabem que [os] levará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 39, 7, 'E agora, SENHOR, o que eu espero? Minha esperança [está] em ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 39, 8, 'Livra-me de todas as minhas transgressões; não me ponhas como humilhado pelo tolo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 39, 9, 'Eu estou calado, não abrirei a minha boca, porque tu fizeste [assim] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 39, 10, 'Tira teu tormento de sobre mim; estou consumido pelo golpe de tua mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 39, 11, 'Ao castigares alguém com repreensões pela maldade, logo tu desfaz o que lhe agrada como traça; certamente todo homem é um nada. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 39, 12, 'Ouve a minha oração, SENHOR; e dá ouvidos ao meu clamor; não te cales de minhas lágrimas, porque eu sou [como] um peregrino para contigo; estrangeiro, como todos os meus pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 39, 13, 'Não prestes atenção em mim [em tua ira] , antes que eu vá, e pereça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 40, 1, 'Salmo de Davi, para o regente: Esperei com esperança no SENHOR, e ele se inclinou a mim, e ouviu o meu clamor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 40, 2, 'Ele me tirou de uma cova de tormento, de um lamaceiro de barro; e pôs os meus pés sobre uma rocha; ele firmou meus passos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 40, 3, 'E pôs em minha boca uma canção nova, um louvor para nosso Deus: muitos [o] verão, e temerão, e confiarão no SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 40, 4, 'Bem-aventurado [é] o homem que põe no SENHOR sua confiança; e não dá atenção aos arrogantes e aos que caminham em direção à mentira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 40, 5, 'Tu, SENHOR meu Deus, multiplicaste para conosco tuas maravilhas e teus planos; eles não podem ser contados em ordem diante de ti; se eu [tentasse] contá-los e falá-los, eles são muito mais do que incontáveis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 40, 6, 'Tu não te agradaste de sacrifício e oferta; [porém] tu me furaste as orelhas; tu não pediste nem holocausto nem oferta de expiação do pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 40, 7, 'Então eu disse: Eis que venho; no rolo do livro está escrito sobre mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 40, 8, 'Meu Deus, eu desejo fazer a tua vontade; e tua Lei está no meio dos meus sentimentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 40, 9, 'Eu anuncio a justiça na grande congregação; eis que não retenho meus lábios; tu, SENHOR sabes [disso] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 40, 10, 'Eu não escondo tua justiça no meio de meu coração; eu declaro tua fidelidade e tua salvação; não escondo tua bondade e tua verdade na grande congregação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 40, 11, 'Tu, SENHOR, não detenhas para comigo tuas misericórdias; tua bondade e tua fidelidade me guardem continuamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 40, 12, 'Porque inúmeros males me cercaram; minhas maldades me prenderam, e eu não pude as ver; elas são muito mais do que os cabelos de minha cabeça, e meu coração me desamparou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 40, 13, 'Seja agradável para ti, SENHOR, tu me livrares; SENHOR, apressa-te ao meu socorro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 40, 14, 'Envergonhem-se, e sejam juntamente humilhados os que buscam a minha alma para a destruírem; tornem-se para trás e sejam envergonhados os que querem o meu mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 40, 15, 'Sejam eles assolados como pagamento de sua humilhação, os que dizem de mim: “Ha-ha!”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 40, 16, 'Fiquem contentes e se alegrem-se em ti todos aqueles que te buscam; digam continuamente os que amam tua salvação: Engrandecido seja o SENHOR!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 40, 17, 'E eu [estou] miserável e necessitado; [mas] o SENHOR cuida de mim; tu [és] meu socorro e meu libertador; Deus meu, não demores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 41, 1, 'Salmo de Davi, para o regente: Bem-aventurado aquele que dá atenção ao miserável; o SENHOR o livrará no dia do mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 41, 2, 'O SENHOR o guardará, e o manterá vivo; ele será bem-aventurado na terra; e tu não o entregarás à vontade de seus inimigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 41, 3, 'O SENHOR o sustentará no leito de enfermidade; na doença dele tu mudas toda a sua cama.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 41, 4, 'Eu disse: SENHOR, tem piedade de mim, sara a minha alma, porque eu pequei contra ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 41, 5, 'Meus inimigos falam mal de mim, [dizendo] : Quando ele morrerá? [Quando] o nome dele perecerá?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 41, 6, 'E se [algum deles] vem me ver, fala coisas sem valor, [e] seu coração junta maldade; ele sai, [e] fala disso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 41, 7, 'Todos os que me odeiam murmuram juntamente de mim; contra mim eles planejam o mal para mim, [dizendo] :'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 41, 8, 'Uma doença maligna está posta sobre ele; e aquele que está deitado não se levantará mais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 41, 9, 'Até o homem [que era] meu amigo íntimo, em quem eu confiava, que comia do meu pão; grandemente levantou contra mim seu calcanhar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 41, 10, 'Porém tu, SENHOR, tem piedade de mim, e levanta-me; e eu lhes darei o pagamento [que merecem] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 41, 11, 'Por isto eu sei que tu te agradas de mim: porque meu inimigo não se declara vencedor sobre mim;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 41, 12, 'E quanto a mim, tu me sustentas em minha sinceridade; e tu me puseste diante de ti para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 41, 13, 'Bendito [seja] o SENHOR, Deus de Israel, para todo o sempre! Amém e Amém!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 42, 1, 'Salmo de instrução para o regente; dos filhos de Coré: Assim como a corça geme de desejo pelas correntes de águas, assim também minha alma geme de desejo por ti, Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 42, 2, 'Minha alma tem sede de Deus, do Deus vivente: Quando entrarei, e me apresentarei diante de Deus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 42, 3, 'Minhas lágrimas têm sido [meu] alimento dia e noite, porque o dia todo me dizem: Onde [está] o teu Deus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 42, 4, 'Disto eu me lembro, e derramo minha alma em mim [com choros] , porque eu ia entre a multidão, [e] com eles entrava na casa de Deus, com voz de alegria e louvor, na festa da multidão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 42, 5, 'Minha alma, por que tu estás abatida, e te inquietas em mim? Espera em Deus; pois eu o louvarei pelas suas salvações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 42, 6, 'Deus meu, minha alma está abatida dentro de mim; por isso eu me lembro de ti desde a terra do Jordão, e dos hermonitas, desde o monte Mizar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 42, 7, 'Um abismo chama [outro] abismo, ao ruído de suas cascatas; todos as tuas ondas e vagas têm passado sobre mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 42, 8, '[Mas] de dia o SENHOR mandará sua misericórdia, e de noite a canção dele estará comigo; uma oração ao Deus de minha vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 42, 9, 'Direi a Deus, minha rocha: Por que tu te esqueces de mim? Por que eu ando em sofrimento pela opressão do inimigo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 42, 10, 'Meus adversários me afrontam com uma ferida mortal em meus ossos, ao me dizerem todo dia: Onde [está] o teu Deus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 42, 11, 'Por que estás abatida, minha alma? E por que te inquietas em mim? Espera em Deus; porque eu ainda o louvarei; ele é a minha salvação e o meu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 43, 1, 'Faze-me justiça, ó Deus, e defende minha causa contra a nação impiedosa; livra-me do homem enganador e perverso;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 43, 2, 'Pois tu és o Deus de minha força. Por que tu me rejeitas? Por que ando em sofrimento pela opressão do inimigo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 43, 3, 'Envia tua luz e tua verdade, para que elas me guiem, para que me levem ao monte de tua santidade e a tuas habitações;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 43, 4, 'E eu entre ao altar de Deus, ao Deus da minha maior alegria, e eu te louve com harpa, ó Deus, meu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 43, 5, 'Por que estás abatida, minha alma? E por que te inquietas em mim? Espera em Deus, porque eu ainda o louvarei; ele é a minha salvação e o meu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 44, 1, 'Instrução para o regente; dos filhos de Coré: Ó Deus, com nossos ouvidos ouvimos, nossos pais nos contaram a obra que tu fizeste nos seus dias, nos dias antigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 44, 2, 'Para plantá-los, expulsaste as nações com a tua própria mão; para fazê-los crescer, afligiste os povos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 44, 3, 'Porque não conquistaram a terra pelas espadas deles, nem o braço deles os salvou; mas sim tua mão direita e o teu braço, e a luz de teu rosto; porque tu os favoreceste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 44, 4, 'Deus, tu és meu Rei; ordena salvações a Jacó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 44, 5, 'Por ti venceremos nossos adversários; por teu nome passaremos por cima dos que se levantam contra nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 44, 6, 'Porque minha confiança não está em meu arco; nem minha espada me salvará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 44, 7, 'Pois tu nos salvaste de nossos adversários, e envergonhaste aos que nos odeiam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 44, 8, 'Nós exaltamos a Deus o dia todo; e louvaremos o teu nome para sempre. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 44, 9, 'Mas [agora] tu tens nos rejeitado e envergonhado; e tu não tens saído junto com nossos exércitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 44, 10, 'Tu nos fazes fugir do adversário, e aqueles que nos odeiam saqueiam [de nós] para si.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 44, 11, 'Tu nos entregas como ovelhas para serem comidas, e nos espalhas entre as nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 44, 12, 'Tu vendes a teu povo ao preço de nada, e não aumentas o seu valor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 44, 13, 'Tu nos pões como humilhação por nossos vizinhos; como escárnio e zombaria pelos que estão ao redor de nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 44, 14, 'Tu nos pões como provérbio de escárnio entre as nações; como balançar de cabeça entre os povos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 44, 15, 'Minha humilhação está o dia todo diante de mim; e a vergonha cobre o meu rosto,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 44, 16, 'Pela voz do adversário e do que insulta; por causa do inimigo e do vingador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 44, 17, 'Tudo isto veio sobre nós; porém não nos esquecemos de ti, nem traímos o teu pacto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 44, 18, 'Nosso coração não se voltou para trás, nem nossos passos de desviaram de teu caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 44, 19, 'Tu tens nos afligido num lugar de chacais, e nos cobriste com sobra de morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 44, 20, 'Se tivéssemos esquecido do nome do nosso Deus, e estendido nossas mãos a um outro deus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 44, 21, 'por acaso Deus não o descobriria? Pois ele conhece os segredos do coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 44, 22, 'Mas por causa de ti somos mortos o dia todo; somos considerados como ovelhas para o matadouro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 44, 23, 'Desperta; por que estás dormindo, Senhor? Acorda, não [nos] rejeites para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 44, 24, 'Por que escondes tua face, e te esqueces de nossa humilhação e de nossa opressão?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 44, 25, 'Pois nossa alma está abatida ao pó; nosso ventre está junto à terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 44, 26, 'Levanta-te para nosso socorro; e resgata-nos por tua bondade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 45, 1, 'Instrução e canção de amor, para o regente; dos filhos de Coré, conforme “os lírios”: Meu coração derrama palavras boas; digo meus versos sobre o Rei; minha língua é pena de um habilidoso escriba.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 45, 2, 'Tu és o mais belo dos filhos dos homens; graça foi derramada em teus lábios, por isso Deus te bendisse para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 45, 3, 'Põe tua espada ao redor de tua coxa, ó valente; [com] tua glória e tua honra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 45, 4, 'E [em] tua glória prosperamente cavalga, sobre a palavra da verdade e da justa mansidão; e tua mão direita ensinará coisas temíveis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 45, 5, 'Tuas flechas [são] afiadas no coração dos inimigos do Rei; povos cairão debaixo de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 45, 6, 'Deus, teu trono é eterno e dura para sempre; o cetro de teu reino [é] cetro de equidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 45, 7, 'Tu amas a justiça e odeias a maldade; por isso Deus, o teu Deus te ungiu com azeite de alegria, mais que a teus companheiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 45, 8, 'Todos as tuas roupas [cheiram] a mirra, aloés e cássia; alegram-te desde os palácios de marfim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 45, 9, 'Filhas de reis estão entre tuas damas de honra; e a rainha está à tua direita, [ornada] com o valioso ouro de Ofir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 45, 10, 'Ouve, filha, e olha, e inclina os teus ouvidos; e esquece-te de teu povo, e da casa de teu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 45, 11, 'Então o rei desejará tua beleza; inclina-te a ele, pois ele é teu Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 45, 12, 'E a filha de Tiro, os ricos dentre o povo, suplicarão teu favor com presentes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 45, 13, 'Gloriosa é a filha do Rei dentro [do palácio] ; de fios de ouro é a sua roupa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 45, 14, 'Com roupas bordadas a levarão ao Rei; as virgens atrás dela, suas companheiras, serão trazidas a ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 45, 15, 'Serão trazidas com alegria e grande satisfação; entrarão no palácio do Rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 45, 16, 'Em vez de teus pais, serão teus filhos; tu os porás por príncipes sobre toda a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 45, 17, 'Farei memória de teu nome em toda geração após geração; por isso os povos te louvarão para todo o sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 46, 1, 'Cântico sobre “Alamote”; para o regente, dos filhos de Coré: Deus [é] nosso refúgio e força; socorro oportuno nas angústias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 46, 2, 'Por isso não temeremos, ainda que a terra se mova, e ainda que as montanhas passem ao interior dos mares;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 46, 3, '[Ainda que] suas águas rujam [e] se perturbem, [e] as montanhas tremam por sua braveza. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 46, 4, '[Há] um rio cujos ribeiros alegram a cidade de Deus, o santuário das habitações do Altíssimo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 46, 5, 'Deus [está] no meio dela; ela não será abalada; Deus a ajudará ao romper da manhã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 46, 6, 'As nações gritarão, os reinos se abalarão; [quando] ele levantou a sua voz, a terra se dissolveu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 46, 7, 'O SENHOR dos exércitos [está] conosco; o Deus de Jacó [é] nosso alto refúgio. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 46, 8, 'Vinde, observai os feitos do SENHOR, que faz assolações na terra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 46, 9, 'Que termina as guerras até o fim da terra; ele quebra o arco e corta a lança; ele queima os carros com fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 46, 10, 'Ficai quietos, e sabei que eu sou Deus; eu serei exaltado entre as nações; serei exaltado sobre a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 46, 11, 'O SENHOR dos exércitos [está] conosco; o Deus de Jacó [é] nosso alto refúgio. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 47, 1, 'Salmo para o regente, dos filhos de Coré: Vós todos os povos, batei palmas; clamai a Deus com voz de alegria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 47, 2, 'Porque o SENHOR Altíssimo [é] temível, o grande Rei sobre toda a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 47, 3, 'Ele subjugará aos povos debaixo de nós, e as nações debaixo de nossos pés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 47, 4, 'Ele escolhe para nós nossa herança, a glória de Jacó, a quem ele amou. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 47, 5, 'Deus sobe com gritos de alegria; o SENHOR, com voz de trombeta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 47, 6, 'Cantai louvores a Deus, cantai; cantai louvores ao nosso Rei, cantai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 47, 7, 'Porque Deus é o Rei de toda a terra; cantai louvores com entendimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 47, 8, 'Deus reina sobre as nações; Deus se senta sobre o trono de sua santidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 47, 9, 'Os chefes dos povos se juntaram ao povo do Deus de Abraão, porque os escudos da terra pertencem a Deus, [e] ele é muito exaltado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 48, 1, 'Cântico e salmo, dos filhos de Coré: O SENHOR [é] grande e muito louvável, na cidade de nosso Deus, [no] monte de sua santidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 48, 2, 'Belo de se ver e alegria de toda a terra [é] o monte de Sião, nas terras do norte; a cidade do grande Rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 48, 3, 'Deus [está] em seus palácios, [e] é conhecido como alto refúgio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 48, 4, 'Porque eis que os reis se reuniram; eles juntamente passaram'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 48, 5, 'Eles, [quando] a viram, ficaram maravilhados; assombraram-se, fugiram apressadamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 48, 6, 'Ali o temor os tomou, [e sentiram] dores como as de parto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 48, 7, 'Com o vento do oriente tu quebras os navios de Társis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 48, 8, 'Assim como nós ouvimos, também vimos na cidade do SENHOR dos exércitos, na cidade do nosso Deus; Deus a firmará para sempre. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 48, 9, 'Deus, nós reconhecemos tua bondade no meio de teu templo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 48, 10, 'Conforme o teu nome, ó Deus, assim é o louvor a ti, até os confins da terra; tua mão direita está cheia de justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 48, 11, 'Alegre-se o monte de Sião, fiquem contentes as filhas de Judá, por causa de teus juízos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 48, 12, 'Andai ao redor de Sião, e a circundai; contai suas torres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 48, 13, 'Ponde vosso coração em seus muros de defesa, prestai atenção em seus palácios, para que conteis deles à geração seguinte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 48, 14, 'Porque este Deus [é] nosso Deus para todo o sempre; ele nos acompanhará até a morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 49, 1, 'Salmo para o regente, dos filhos de Coré: Ouvi isto, vós todos os povos; dai ouvidos, todos os moradores do mundo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 49, 2, 'vós, povo, filhos dos homens, tanto os ricos como os pobres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 49, 3, 'Minha boca falará da sabedoria; e o pensamento do meu coração [estará cheio de] entendimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 49, 4, 'Inclinarei meus ouvidos a uma parábola; ao [som] da harpa declararei o meu enigma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 49, 5, 'Por que temeria eu nos dias do mal, [quando] a maldade dos meus adversários me cercar?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 49, 6, 'Eles confiam em seus bens, e se orgulham da abundância de suas riquezas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 49, 7, 'Mas ninguém pode livrar o seu irmão, nem pagar a Deus o seu resgate,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 49, 8, 'porque a redenção da sua alma é caríssima, e sempre será insuficiente'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 49, 9, 'para viver eternamente, e jamais ver a cova.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 49, 10, 'Pois se vê que os sábios morrem, que o tolo e o bruto igualmente perecem; e deixam suas riquezas a outros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 49, 11, 'Seu pensamento interior é que suas casas serão perpétuas, que suas moradas durarão de geração em geração;dão às terras os seus próprios nomes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 49, 12, 'Mas o ser humano, ainda que em honra, não dura para sempre; semelhante é aos animais, que perecem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 49, 13, 'Este é o caminho dos tolos e dos seus seguidores, que se agradam de suas palavras. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 49, 14, 'São como ovelhas levados ao Xeol; a morte se alimentará deles. Os corretos os dominarão pela manhã, e sua beleza será consumida no Xeol, longe de sua morada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 49, 15, 'Mas Deus resgatará a minha alma da violência do mundo dos mortos, pois ele me tomará [consigo] . (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 49, 16, 'Não temas quando um homem enriquece, quando a glória de sua casa se engrandece.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 49, 17, 'Pois ele, quando morrer, nada levará; nem sua glória o seguirá abaixo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 49, 18, 'Ainda que, em vida, tenha pronunciado a si mesmo a bênção “Louvam-te ao fazeres o bem a ti”,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 49, 19, 'ele, porém, se juntará à geração de seus pais; nunca mais verão a luz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 49, 20, 'O homem em posição de honra que não tem entendimento é semelhante aos animais, que perecem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 50, 1, 'Salmo de Asafe: Deus, o SENHOR Deus fala e chama a terra, desde onde o sol nasce até onde ele se põe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 50, 2, 'Desde Sião, a perfeição da beleza, Deus mostra seu imenso brilho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 50, 3, 'Nosso Deus virá, e não ficará calado; fogo queimará adiante dele, e ao redor dele haverá grande tormenta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 50, 4, 'Ele chamará aos céus do alto, e à terra, para julgar a seu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 50, 5, 'Ajuntai-me meus santos, que confirmam meu pacto por meio de sacrifício.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 50, 6, 'E os céus anunciarão sua justiça, pois o próprio Deus é o juiz. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 50, 7, 'Ouve, povo meu, e eu falarei; eu darei testemunho contra ti, Israel; eu sou Deus, o teu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 50, 8, 'Eu não te repreenderei por causa de teus sacrifícios, porque teus holocaustos estão continuamente perante mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 50, 9, 'Não tomarei bezerro de tua casa, [nem] bodes de teus currais;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 50, 10, 'Porque todo animal das matas é meu, [e também] os milhares de animais selvagens das montanhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 50, 11, 'Conheço todas as aves das montanhas, e as feras do campo [estão] comigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 50, 12, 'Se eu tivesse fome, não te diria, porque meu é o mundo, e tudo o que nele há.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 50, 13, 'Comeria eu carne de touros, ou beberia sangue de bodes?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 50, 14, 'Oferece a Deus sacrifício de louvor, e paga ao Altíssimo os teus votos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 50, 15, 'E clama a mim no dia da angústia; e eu te farei livre, e tu me glorificarás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 50, 16, 'Mas Deus diz ao perverso: Para que tu recitas meus estatutos, e pões meu pacto em tua boca?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 50, 17, 'Pois tu odeias a repreensão, e lança minhas palavras para detrás de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 50, 18, 'Se vês ao ladrão, tu consentes com ele; e tens tua parte com os adúlteros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 50, 19, 'Com tua boca pronuncias o mal, e tua língua gera falsidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 50, 20, 'Tu te sentas [e] falas contra teu irmão; contra o filho de tua mãe tu dizes ofensas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 50, 21, 'Tu fazes estas coisas, e eu fico calado; pensavas que eu seria como tu? Eu te condenarei, e mostrarei [teus males] diante de teus olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 50, 22, 'Entendei, pois, isto, vós que vos esqueceis de Deus; para que eu não [vos] faça em pedaços, e não haja quem [vos] livre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 50, 23, 'Quem oferece sacrifício de louvor me glorificará, e ao que cuida de seu caminho, eu lhe mostrarei a salvação de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 51, 1, 'Salmo de Davi, para o regente, quando o profeta Natã veio até ele, depois dele ter praticado adultério com Bate-Seba: Tem misericórdia de mim, ó Deus, conforme a tua bondade; desfaz minhas transgressões conforme a abundância de tuas misericórdias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 51, 2, 'Lava-me bem de minha perversidade, e purifica-me de meu pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 51, 3, 'Porque eu reconheço minhas transgressões, e meu pecado está continuamente diante de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 51, 4, 'Contra ti, somente contra ti pequei, e fiz o mal segundo teus olhos; para que estejas justo no que dizeres, e puro no que julgares.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 51, 5, 'Eis que em perversidade fui formado, e em pecado minha mãe me concebeu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 51, 6, 'Eis que tu te agradas da verdade interior, e no oculto tu me fazes conhecer sabedoria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 51, 7, 'Limpa-me do pecado com hissopo, e ficarei limpo; lava-me, e eu serei mais branco que a neve.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 51, 8, 'Faça-me ouvir alegria e contentamento, [e] meus ossos, que tu quebraste, se alegrarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 51, 9, 'Esconde tua face de meus pecados, e desfaz todas as minhas perversidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 51, 10, 'Cria em mim um coração puro, ó Deus; e renova um espírito firme em meu interior.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 51, 11, 'Não me rejeites de tua face, e não tires teu Espírito Santo de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 51, 12, 'Restaura a alegria de tua salvação, e que tu me sustentes com um espírito de boa vontade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 51, 13, '[Então] eu ensinarei aos transgressores os teus caminhos, e os pecadores se converterão a ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 51, 14, 'Livra-me das [transgressões] por derramamento de sangue, ó Deus, Deus de minha salvação; e minha língua louvará alegremente tua justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 51, 15, 'Abre, Senhor, os meus lábios, e minha boca anunciará louvor a ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 51, 16, 'Porque tu não te agradas de sacrifícios, pois senão eu te daria; tu não te alegras de holocaustos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 51, 17, 'Os sacrifícios a Deus são um espírito quebrado [em arrependimento] ; tu não desprezarás um coração quebrado e triste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 51, 18, 'Faze bem a Sião conforme tua boa vontade; edifica os muros de Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 51, 19, 'Então tu te agradarás dos sacrifícios de justiça, dos holocaustos, e das ofertas queimadas; então oferecerão bezerros sobre teu altar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 52, 1, 'Instrução de Davi, para o regente, quando Doegue, o edomita, veio, e contou a Saul, dizendo: Davi veio à casa de Aimeleque: Por que tu, homem poderoso, te orgulhas no mal? A bondade de Deus continua o dia todo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 52, 2, 'Tua língua planeja maldades; [é] como navalha afiada, que gera falsidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 52, 3, 'Tu amas mais o mal que o bem, [e] a mentira mais do que falar justiça. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 52, 4, 'Tu amas todas as palavras de destruição, ó língua enganadora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 52, 5, 'Porém Deus te derrubará para sempre; ele te tomará, e te arrancará para fora da tenda; e te eliminará de toda a terra dos viventes. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 52, 6, 'E os justos [o] verão, e temerão; e rirão dele, [dizendo] :'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 52, 7, 'Eis aqui o homem que não pôs sua força em Deus, mas [preferiu] confiar a abundância de suas riquezas, e fortaleceu em sua maldade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 52, 8, 'Mas eu [serei] como a oliveira verde na casa de Deus; confio na bondade de Deus para todo o sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 52, 9, 'Eu te louvarei para sempre, por causa do que fizeste; e terei esperança em teu nome, porque tu és bom perante teus santos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 53, 1, 'Instrução de Davi, para o regente, sobre “Maalate”: O tolo diz em seu coração: Não há Deus.Eles se corrompem, e cometem abominável perversidade, ninguém há que faça o bem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 53, 2, 'Deus olhou desde os céus para os filhos dos homens, para ver se havia alguém prudente, que buscasse a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 53, 3, 'Todos se desviaram, juntamente se fizeram detestáveis; ninguém há que faça o bem, nem um sequer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 53, 4, 'Será que não tem conhecimento os praticantes de maldade, que devoram a meu povo, [como se] comessem pão? Eles não clamam a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 53, 5, 'Ali eles terão grande medo, [onde] não havia medo; porque Deus espalhou os ossos daquele que te cercava; tu os humilhaste, porque Deus os rejeitou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 53, 6, 'Ah, que de Sião venha a salvação de Israel! Quando Deus restaurar seu povo de seu infortúnio, Jacó jubilará, Israel se alegrará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 54, 1, 'Instrução de Davi, para o regente, para instrumentos de cordas, quando os zifeus vieram, e disseram a Saul: “Não está Davi escondido entre nós?”: Deus, salva-me por teu nome; e faze-me justiça por teu poder.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 54, 2, 'Deus, ouve minha oração; inclina teus ouvidos aos dizeres de minha boca;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 54, 3, 'Porque estranhos se levantam contra mim, e [homens] terríveis procuram [matar] a minha alma; não põem a Deus diante dos olhos deles. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 54, 4, 'Eis que Deus é o que me socorre; o Senhor [está] com aqueles que sustentam a minha alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 54, 5, 'Ele retribuirá com o mal aos que me espiam [contra mim] ; tu os elimina por tua verdade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 54, 6, 'De boa vontade eu te oferecerei sacrifícios; louvarei o teu nome, SENHOR, porque é bom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 54, 7, 'Porque tu tens me livrado de toda angústia; e meus olhos verão [o fim] de meus inimigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 55, 1, 'Instrução de Davi, para o regente, com instrumento de cordas: Deus, inclina os teus ouvidos à minha oração; e não te escondas de minha súplica.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 55, 2, 'Presta atenção em mim, e responde-me; clamo por meu sofrimento, e grito,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 55, 3, 'Por causa da voz do inimigo, [e] pela opressão do perverso; porque me preparam [suas] maldades, e com furor eles me odeiam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 55, 4, 'Meu coração sofre dores em meu interior, e terrores de morte caíram sobre mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 55, 5, 'Temor e tremor vêm sobre mim, e o horror me toma por completo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 55, 6, 'Então eu digo: Ah, quem me dera se eu tivesse asas como uma pomba! Eu voaria, e pousaria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 55, 7, 'Eis que eu fugiria para longe, e ficaria no deserto. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 55, 8, 'Eu me apressaria para escapar do vento violento [e] da tempestade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 55, 9, 'Devora-os, Senhor, divide a língua deles; porque tenho visto violência e briga na cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 55, 10, 'Dia e noite cercam sobre seus muros; perversidade e opressão há dentro dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 55, 11, 'Coisas destrutivas [estão] dentro dela; e a falsidade e o engano não sai de suas praças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 55, 12, 'Porque não [é] um inimigo o que me insulta, pois [se fosse] eu o suportaria; nem é alguém que me odeia o que se engrandece contra mim, pois [se fosse] eu me esconderia dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 55, 13, 'Mas és tu, homem semelhante a mim; meu guia, e meu conhecido;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 55, 14, 'Que juntos agradavelmente dávamos conselhos [um ao outro] ; na casa de Deus andávamos entre a multidão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 55, 15, 'Que a morte os tome de surpresa, e desçam ao Xeol vivos; porque há maldades em suas moradas, e no meio deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 55, 16, 'Clamarei a Deus, e o SENHOR me salvará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 55, 17, 'À tarde, e pela manhã, e ao meio dia, orarei e clamarei; e ele ouvirá a minha voz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 55, 18, 'Ele resgatou em paz a minha alma da batalha [que havia] contra mim; porque muitos vieram para me [prejudicar] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 55, 19, 'Deus ouvirá, e os humilhará, ele que governa desde os princípios dos tempos. (Selá)Porque eles não mudam [de comportamento] , nem temem a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 55, 20, '[Meu antigo amigo] se voltou contra os que tinham paz com ele, e violou seu pacto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 55, 21, 'Sua boca é agradável como a manteiga, mas seu coração [deseja] a guerra; suas palavras [parecem] mais suaves que o azeite, mas são espadas prontas para o ataque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 55, 22, 'Entrega [tuas preocupações] ao SENHOR, e ele te sustentará; ele não permitirá que o justo fique caído para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 55, 23, 'Porém tu, SENHOR, farás com que eles desçam ao poço da perdição; os homens sanguinários e enganadores não viverão a metade de seus dias; e eu confiarei em ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 56, 1, 'Salmo “Mictão” de Davi para o regente, conforme “pombas silenciosas ao longe”, quando os filisteus o prenderam em Gate: Tem misericórdia de mim, ó Deus, porque o homem procura me devorar; todo o dia ele me oprime em lutas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 56, 2, 'Os inimigos que me espiam querem [me] devorar todo dia; porque muitos lutam contra mim, ó Altíssimo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 56, 3, 'No dia em que eu tiver medo, eu confiarei em ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 56, 4, 'Por causa de Deus eu louvarei sua palavra; confio em Deus, não temerei; o que pode a mera carne fazer contra mim?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 56, 5, 'Todos os dias eles distorcem minhas palavras; todos os pensamentos deles sobre mim são para o mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 56, 6, 'Eles se reúnem e se escondem; eles espiam os meus passos, como que esperando a [morte] de minha alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 56, 7, 'Por acaso eles escaparão em [suas] maldades? Derruba com ira aos povos, ó Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 56, 8, 'Tu contaste as voltas que dei por causa de meu sofrimento; põe minhas lágrimas em teu odre; não estão elas em teu livro?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 56, 9, 'No dia em que eu clamar, então meus inimigos se voltarão para trás; isto eu sei, que Deus [está] comigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 56, 10, 'Por causa de Deus eu louvarei [sua] palavra; por causa do SENHOR eu louvarei [sua] palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 56, 11, 'Em Deus eu confio, não temerei; o que o homem pode me fazer?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 56, 12, 'Tuas promessas, SENHOR, estão sobre mim; oferecerei agradecimentos a ti;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 56, 13, 'Porque tu resgataste minha alma da morte, e meus pés não [deixaste] tropeçar; para [eu] andar diante de Deus na luz dos viventes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 57, 1, 'Salmo “Mictão” para o regente, conforme “Altachete”; de Davi, quando fugia de diante de Saul, na caverna: Tem misericórdia de mim, ó Deus, tem misericórdia de mim; porque minha alma confia em ti, e eu me refugio sob a sombra de tuas asas, até que os [meus] problemas passem de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 57, 2, 'Clamarei ao Deus Altíssimo; a Deus, que cumprirá [sua obra] em mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 57, 3, 'Ele enviará desde os céus e me livrará, humilhando ao que procura me demorar. (Selá)Deus enviará sua bondade e sua verdade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 57, 4, 'Minha alma está no meio dos leões, estou deitado [entre] brasas ardentes, filhos de homens, cujos dentes são lanças e flechas, e a língua deles são espada afiada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 57, 5, 'Exalta-te sobre os céus, ó Deus; [esteja] tua glória sobre toda a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 57, 6, 'Prepararam uma rede de armadilha para os meus passos, minha alma [estava] abatida; cavaram perante mim uma cova, [porém] eles mesmos caíram nela. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 57, 7, 'Firme está meu coração, ó Deus; meu coração está firme; eu cantarei, e louvarei com músicas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 57, 8, 'Desperta-te, ó glória minha! Desperta, lira e harpa; despertarei ao amanhecer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 57, 9, 'Eu te louvarei entre os povos, Senhor; cantarei louvores a ti entre as nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 57, 10, 'Pois tua bondade é grande, [alcança] até os céus; e a tua fidelidade até as nuvens mais altas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 57, 11, 'Exalta-te sobre os céus, ó Deus; [esteja] tua glória sobre toda a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 58, 1, 'Salmo “Mictão” de Davi, para o regente, conforme “Altachete”: Congregação, por acaso falais verdadeiramente o que é justo? Vós, Filhos dos homens, julgais corretamente?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 58, 2, 'Na verdade vós praticais perversidades em [vosso] coração; sobre a terra pesais a violência de vossas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 58, 3, 'Os perversos se desviam desde o ventre da mãe; afastam-se desde o ventre os mentirosos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 58, 4, 'O veneno deles [é] semelhante ao veneno de serpente; são como a cobra surda, que tapa seus ouvidos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 58, 5, 'Para não ouvirem a voz dos encantadores, do encantador sábio em encantamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 58, 6, 'Deus, quebra os dentes deles em suas bocas; arranca os queixos dos filhos dos leões, SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 58, 7, 'Que eles escorram como águas, que vão embora; quando ele armar sua flecha, sejam eles cortados em pedaços.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 58, 8, 'Como a lesma, que se desmancha, que [assim] saiam embora; como o aborto de mulher, [assim também] nunca vejam o sol.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 58, 9, 'Antes que vossas panelas sintam os espinhos, tanto vivos, como aquecidos, ele os arrebatará furiosamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 58, 10, 'O justo se alegrará ao ver a vingança; [e] lavará seus pés no sangue do perverso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 58, 11, 'Então o homem dirá: Certamente há recompensa para o justo; certamente há Deus, que julga na terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 59, 1, 'Salmo “Mictão” de Davi, para o regente, conforme “Altachete”, quando Saul enviou pessoas para vigiarem sua casa e o matarem: Livra-me de meus inimigos, ó Deus meu; protege-me dos que se levantam contra mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 59, 2, 'Livra-me dos que praticam perversidade, e salva-me dos homens sanguinários;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 59, 3, 'Porque eis que eles põem ciladas à minha alma; fortes se juntam contra mim; [ainda que] eu não tenha cometido transgressão nem pecado, ó SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 59, 4, 'Eles correm sem [eu ter] culpa; desperta para me encontrar, e olha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 59, 5, 'Tu, SENHOR, Deus dos exércitos, Deus de Israel, desperta para julgar a todas estas nações; não tenhas misericórdia de nenhum dos enganadores que praticam perversidade. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 59, 6, 'Eles voltam ao anoitecer, latem como cães, e rodeiam a cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 59, 7, 'Eis que vomitam com as bocas deles, seus lábios [são como] espadas; porque [dizem] : Quem ouve?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 59, 8, 'Porém tu, SENHOR, rirás deles; zombarás de todas as nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 59, 9, '[Por causa] de sua força, eu te aguardarei; porque Deus é o meu refúgio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 59, 10, 'O Deus que tem bondade para comigo me antecederá; Deus me fará ver [o fim] dos meus inimigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 59, 11, 'Não os mates, para que meu povo não se esqueça; faze-os fugir de um lado para o outro pelo teu poder, e abate-os; ó Senhor, escudo nosso;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 59, 12, '[Por causa do] pecado da boca deles [e da] palavra de seus lábios; e sejam presos em sua arrogância pelas maldições e pelas mentiras que contam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 59, 13, 'Destrói [-os] em [tua] ira; destrói [-os] para que nunca mais existam; para que saibam que Deus governa em Jacó até os limites da terra. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 59, 14, 'Eles voltam ao anoitecer, latem como cães, e rodeiam a cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 59, 15, 'Andam de um lado para o outro por comida, e rosnam se não estiverem saciados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 59, 16, 'Mas eu cantarei [sobre] tua força; e pela manhã com alegria louvarei tua bondade; porque tu tens sido meu alto refúgio e abrigo no dia da minha angústia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 59, 17, 'Cantarei louvores a ti, [que és] minha força; porque Deus é o meu refúgio, ó Deus de bondade para comigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 60, 1, 'Salmo “Mictão” de Davi, de ensinamento, para o regente, conforme “Susanedute”, quando lutou contra os de Arã-Naraim e Arã-Zobá, e Joabe voltou vitorioso, tendo ferido no Vale do Sal a doze mil dos de Edom: Deus, tu nos rejeitaste, e nos quebraste; tu te encheste de ira. [Por favor] , restaura-nos!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 60, 2, 'Tu fizeste a terra tremer, [e] a abriste; cura suas rachaduras, porque ela está abalada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 60, 3, 'Mostraste ao teu povo coisas duras; nos fizeste beber vinho perturbador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 60, 4, 'Deste uma bandeira aos que te temem, para a erguerem por causa da verdade. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 60, 5, 'Para que os teus amados sejam livrados; salva-nos com tua mão direita, e responde-nos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 60, 6, 'Deus falou em seu santuário: Eu me alegrarei; repartirei a Siquém e medirei o vale de Sucote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 60, 7, 'Meu [é] Gileade, e meu [é] Manassés; e Efraim [é] a força de minha cabeça; Judá [é] meu legislador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 60, 8, 'Moabe [é] minha bacia de lavar; sobre Edom lançarei minha sandália; gritarei de alegria sobre a Filístia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 60, 9, 'Quem me levará a uma cidade fortificada? Quem me guiará até Edom?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 60, 10, 'Não serás tu, ó Deus, que tinha nos rejeitado? Não saías tu, ó Deus, com nossos exércitos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 60, 11, 'Dá-nos socorro para a angústia; porque a salvação de [origem] humana é inútil.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 60, 12, 'Com Deus faremos coisas grandiosas; e ele atropelará nossos adversários.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 61, 1, 'Salmo de Davi, para o regente, com instrumento de cordas: Ouve, ó Deus, o meu clamor; presta atenção à minha oração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 61, 2, 'Desde o limite da terra eu clamo a ti, pelo sofrimento do meu coração; leva-me para uma rocha alta para mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 61, 3, 'Pois tu tens sido o meu refúgio [e] torre forte perante o inimigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 61, 4, 'Eu habitarei em tua tenda para sempre; tomarei refúgio [me] escondendo sob tuas asas. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 61, 5, 'Pois tu, ó Deus, ouviste meus votos; tu tens [me] dado a herança dos que temem o teu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 61, 6, 'Acrescentarás dias e mais dias ao Rei; seus anos serão como de geração em geração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 61, 7, 'Ele habitará para sempre diante de Deus; prepara que [tua] bondade e fidelidade o guardem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 61, 8, 'Assim cantarei ao teu nome para sempre, para eu pagar meus votos dia após dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 62, 1, 'Salmo de Davi para o regente, conforme “Jedutum”: Certamente minha alma se aquieta por causa de Deus; dele [vem] minha salvação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 62, 2, 'Certamente ele [é] minha rocha, minha salvação e meu refúgio; não serei muito abalado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 62, 3, 'Até quando atacareis um homem? Todos vós sereis mortos; [sereis] como um parede tombada e uma cerca derrubada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 62, 4, 'Eles somente tomam conselhos sobre como lançá-lo abaixo de sua alta posição; agradam-se de mentiras; falam bem com suas bocas, mas amaldiçoam em seus interiores. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 62, 5, 'Tu, porém, ó minha alma, aquieta-te em Deus; porque ele [é] minha esperança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 62, 6, 'Certamente ele [é] minha rocha, minha salvação [e] meu refúgio; não me abalarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 62, 7, 'Em Deus [está] minha salvação e minha glória; em Deus [está] minha força e meu refúgio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 62, 8, 'Confiai, povo, nele em todo o tempo; derramai vosso coração diante dele; Deus [é] nosso refúgio. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 62, 9, 'Pois os filhos dos seres humanos são nada; os filhos do homem são mentira; pesados juntos [são mais leves] que o vazio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 62, 10, 'Não confieis na opressão, nem no roubo; nem sejais inúteis; quando tiverdes bens, não ponhais [neles vosso] coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 62, 11, 'Deus falou uma vez; eu ouvi duas vezes: que [de] Deus [vem] o poder.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 62, 12, 'Também é tua, Senhor, a bondade; pois tu pagarás a [cada] homem conforme sua obra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 63, 1, 'Salmo de Davi, quando ele estava no deserto de Judá: Deus, tu [és] meu Deus. Eu te busco ao amanhecer; minha alma tem sede de ti, minha carne muito te deseja, em terra seca, cansativa, sem águas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 63, 2, 'Para que eu te veja em teu santuário, para ver tua força e tua glória.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 63, 3, 'Porque tua bondade [é] melhor que a vida; meus lábios te louvarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 63, 4, 'Assim te bendirei em minha vida; por teu nome levantarei minhas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 63, 5, 'Minha alma será saciada, como que de gorduras e muita comida; e minha boca te louvará com lábios alegres,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 63, 6, 'Quando eu me lembrar de ti em minha cama; nas vigílias da noite meus pensamentos estarão em ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 63, 7, 'Porque tu tens sido meu socorro; e à sombra de tuas asas cantarei de alegria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 63, 8, 'Minha alma está apegada a ti; tua mão direita me sustenta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 63, 9, 'Porém aqueles que procuram assolar a minha alma irão para as profundezas da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 63, 10, 'Eles serão derrubados pela força da espada; serão repartidos entre raposas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 63, 11, 'Mas o Rei se alegrará em Deus; todo o que por ele jurar se alegrará, porque a boca dos mentirosos será tapada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 64, 1, 'Salmo de Davi, para o regente: Ouve, Deus, minha voz, em minha meditação [de súplica] ; guarda minha vida do terror do inimigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 64, 2, 'Esconde-me do grupo dos malignos, e do ajuntamento dos praticantes de maldade,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 64, 3, 'Que afiam sua língua como [se fosse] espada; e armaram palavras amargas [como se fossem] flechas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 64, 4, 'Para atirarem no inocente às escondidas; disparam apressadamente contra ele, e não têm medo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 64, 5, 'Eles são ousados para [fazerem] coisas más, comentam sobre como esconder armadilhas, [e] dizem: Quem as verá?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 64, 6, 'Eles buscam por perversidades; procuram tudo o que pode ser procurado, até o interior de [cada] homem, e as profundezas do coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 64, 7, 'Mas Deus os atingirá com flecha de repente; e [logo] serão feridos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 64, 8, 'E a língua deles fará com que tropecem em si mesmos; todo aquele que olhar para eles se afastará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 64, 9, 'E todos os homens terão medo, e anunciarão a obra de Deus, e observarão cuidadosamente o que ele fez.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 64, 10, 'O justo se alegará no SENHOR, e confiará nele; e todos os corretos de coração [o] glorificarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 65, 1, 'Salmo e cântico de Davi, para o regente: A ti, Deus, [pertence] a tranquilidade [e] o louvor em Sião; e a ti será pago o voto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 65, 2, 'Tu, que ouves as orações; toda carne virá a ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 65, 3, 'Perversidades têm me dominado, [porém] tu tiras a culpa de nossas transgressões.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 65, 4, 'Bem-aventurado [é] aquele a quem tu escolhes, e [o] fazes aproximar, para que habite em teus cômodos; seremos fartos do bem de tua casa, [na] santidade de teu templo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 65, 5, 'Tu nos responderá de forma justa [por meio de] coisas temíveis. O Deus de nossa salvação [é] a confiança de todos os limites da terra, e dos lugares mais distantes do mar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 65, 6, 'Ele [é] o que firma os montes com sua força, revestido de poder.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 65, 7, 'Ele é o que amansa o ruído dos mares, o ruído de suas ondas, e o tumulto dos povos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 65, 8, '[Até] os que habitam nos lugares mais distantes temem teus sinais; tu fazes alegres o nascer e o pôr do sol.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 65, 9, 'Tu visitas a terra, e a regas; tu a enriqueces; o rio de Deus [está] cheio de águas; tu preparas [a terra] , e lhes dá trigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 65, 10, 'Enche seus regos de [águas] ,fazendo-as descer em suas margens; com muita chuva a amoleces, [e] abençoas o que dela brota.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 65, 11, 'Coroas o ano com tua bondade; e teus caminhos transbordam fartura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 65, 12, 'Eles são derramados [sobre] os pastos do deserto; e os morros se revestem de alegria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 65, 13, 'Os campos se revestem de rebanhos, e os vales são cobertos de trigo; e por isso se alegram e cantam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 66, 1, 'Cântico e salmo para o regente: Gritai de alegria a Deus toda a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 66, 2, 'Cantai a glória do nome dele; reconhecei a glória de seu louvor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 66, 3, 'Dizei a Deus: Tu [és] temível [em] tuas obras; pela grandeza de tua força os teus inimigos se sujeitarão a ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 66, 4, 'Toda a terra te adorará, e cantará a ti; cantarão ao teu nome. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 66, 5, 'Vinde, e vede os atos de Deus; a obra dele é temível aos filhos dos homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 66, 6, 'Ele fez o mar ficar seco, passaram o rio a pé; ali nos alegramos nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 66, 7, 'Ele governa com seu poder para sempre; seus olhos vigiam as nações; não se exaltem os rebeldes. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 66, 8, 'Vós povos, bendizei a nosso Deus, e fazei ouvir a voz do louvor a ele,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 66, 9, 'Que conserva nossas almas em vida, e não permite que nossos pés se abalem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 66, 10, 'Porque tu, Deus, tem nos provado; tu nos refinas como se refina a prata.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 66, 11, 'Tu nos levaste a uma rede; prendeste-nos em nossas cinturas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 66, 12, 'Fizeste um homem cavalgar sobre nossas cabeças; passamos pelo fogo e pela água, porém tu nos tiraste para um [lugar] confortável.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 66, 13, 'Entrarei em tua casa com holocaustos; pagarei a ti os meus votos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 66, 14, 'Que meus lábios pronunciaram, e minha boca falou, quando eu estava angustiado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 66, 15, 'Eu te oferecerei holocaustos de animais gordos, com incenso de carneiros; prepararei bois com bodes. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 66, 16, 'Vinde, ouvi, todos vós que temeis a Deus, e eu contarei o que ele fez à minha alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 66, 17, 'Clamei a ele com minha boca, e ele foi exaltado pela minha língua.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 66, 18, 'Se eu tivesse dado valor para a maldade em meu coração, o Senhor não teria [me] ouvido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 66, 19, 'Mas certamente Deus [me] ouviu; ele prestou atenção à voz de minha oração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 66, 20, 'Bendito seja Deus, que não ignorou minha oração, nem sua bondade [se desviou] de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 67, 1, 'Salmo e cântico, para o regente, com instrumento de cordas: Que Deus tenha misericórdia de nós, e nos abençoe; que ele brilhe seu rosto sobre nós. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 67, 2, 'Para que o teu caminho seja conhecido na terra, [e] todos as nações [conheçam] tua salvação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 67, 3, 'Louvem os povos a ti, ó Deus, louvem a ti todos os povos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 67, 4, 'Que as nações se alegrem e cantem de alegria, pois tu julgarás aos povos com equidade, e guiarás as nações na terra. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 67, 5, 'Louvem os povos a ti, ó Deus, louvem a ti todos os povos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 67, 6, 'Que a terra dê seu fruto, [e] que Deus, nosso Deus, nos abençoe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 67, 7, 'Deus nos abençoará, e todos os limites da terra o temerão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 68, 1, 'Salmo e canção de Davi, para o regente: Deus se levantará, [e] seus inimigos serão dispersos, e os que o odeiam fugirão de sua presença.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 68, 2, 'Assim como a fumaça se espalha, tu os espalharás; assim como a cera que se derrete diante do fogo, [assim também] os perversos perecerão diante de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 68, 3, 'Mas os justos se alegrarão, [e] saltarão de prazer perante Deus, e se encherão de alegria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 68, 4, 'Cantai a Deus, cantai louvores ao seu nome; exaltai aquele que anda montado sobre as nuvens, pois EU-SOU é o seu nome; e alegrai [-vos] diante dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 68, 5, '[Ele é] o pai dos órfãos, e juiz que defende as viúvas; Deus na habitação de sua santidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 68, 6, 'Deus que faz os solitários viverem em uma família, e liberta os prisioneiros; mas os rebeldes habitam em terra seca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 68, 7, 'Deus, quando tu saías perante teu povo, enquanto caminhavas pelo deserto (Selá),'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 68, 8, 'A terra se abalava, e os céus se derramavam perante a presença de Deus; neste Sinai, diante da presença de Deus, o Deus de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 68, 9, 'Tu fizeste a chuva cair abundantemente, e firmaste tu herança, que estava cansada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 68, 10, 'Nela o teu rebanho habitou; por tua bondade, Deus, sustentaste ao miserável.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 68, 11, 'O Senhor falou; grande é o exército das que anunciam as boas novas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 68, 12, 'Reis de exércitos fugiam apressadamente; e aquela que ficava em casa repartia os despojos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 68, 13, 'Ainda que estivésseis cercados por ambos os lados, [estais protegidos] como que por asas de pomba, cobertas de prata, e suas penas revestidas de ouro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 68, 14, 'Quando o Todo-Poderoso espalhou os reis, houve neve em Salmom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 68, 15, 'O monte de Deus [é como] o monte de Basã; [é] um monte bem alto, [como] o monte de Basã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 68, 16, 'Por que olhais com inveja, ó montes altos? A este monte Deus desejou para ser sua habitação; e o SENHOR habitará [nele] para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 68, 17, 'As carruagens de Deus são várias dezenas de milhares; o Senhor está entre elas, [como] em Sinai, em [seu] santuário.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 68, 18, 'Tu subiste ao alto, levaste cativos, recebeste bens dos homens, até dos rebeldes, para que [ali] o SENHOR Deus habitasse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 68, 19, 'Bendito seja o Senhor; dia após dia ele nos carrega; Deus [é] nossa salvação. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 68, 20, 'Nosso Deus [é] um Deus de salvação; e com o Senhor DEUS há livramento para a morte;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 68, 21, 'Pois Deus ferirá a cabeça de seus inimigos, o topo da cabeça, onde ficam os cabelos, daquele que anda na prática de suas transgressões.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 68, 22, 'O Senhor disse: Eu [os] farei voltar de Basã; eu [os] farei voltar das profundezas do mar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 68, 23, 'Para que metas teu pé no sangue dos teus inimigos; e nele [também] terá uma parte a língua de cada um de teus cães.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 68, 24, 'Viram teus caminhos, ó Deus; os caminhos de meu Deus, meu Rei, no santuário.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 68, 25, 'Os cantores vieram adiante, depois os instrumentistas; entre eles as virgens tocadoras de tamborins.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 68, 26, 'Bendizei a Deus nas congregações; [bendizei] ao SENHOR, desde a fonte de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 68, 27, 'Ali [está] o pequeno Benjamim, que domina sobre eles; os chefes de Judá e a congregação deles; os chefes de Zebulom, [e] os chefes de Nafitali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 68, 28, 'Teu Deus ordenou tua força; fortalece, ó Deus, o que já operaste por nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 68, 29, 'Ao teu templo, em Jerusalém, os Reis te trarão presentes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 68, 30, 'Repreende a fera das canas, a multidão de touros, juntamente com as bezerras dos povos; aos que humilham a si mesmos em [troca] de peças e prata; dissipa aos povos que gostam da guerra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 68, 31, 'Embaixadores virão do Egito; Cuxe correrá para [estender] suas mãos a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 68, 32, 'Reinos da terra, cantai a Deus; cantai louvores ao Senhor. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 68, 33, 'Ele anda montado por entre os céus desde os tempos antigos; eis que sua voz fala poderosamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 68, 34, 'Reconhecei o poder de Deus; sobre Israel [está] sua exaltação, e sua força [está] nas altas nuvens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 68, 35, 'Deus, tu és temível desde teus santuários; o Deus de Israel é o que dá força e poder ao povo. Bendito seja Deus!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 69, 1, 'Salmo de Davi, para o regente, conforme “os lírios”: Salva-me, ó Deus, porque as águas têm entrado [e encoberto] a minha alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 69, 2, 'Afundei-me em um profundo lamaçal, onde não se pode ficar em pé; entrei nas profundezas das águas, e a corrente está me levando.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 69, 3, 'Já estou cansado de clamar, minha garganta enrouqueceu; meus olhos desfaleceram, enquanto espero pelo meu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 69, 4, 'Os que me odeiam sem motivo são mais numerosos que os cabelos de minha cabeça; são poderosos os que procuram me arruinar, os que por falsidades se fazem meus inimigos; tive que pagar de volta aquilo que não furtei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 69, 5, 'Tu, Deus, sabes como sou tolo; e meus pecados não estão escondidos perante ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 69, 6, 'Não sejam envergonhados por minha causa aqueles que te esperam, ó Senhor DEUS dos exércitos; não sejam humilhados por minha causa os que te buscam, ó Deus de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 69, 7, 'Porque por causa de ti aguentei ser insultado; a humilhação cobriu o meu rosto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 69, 8, 'Tornei-me estranho aos meus irmãos; e desconhecido aos filhos de minha mãe;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 69, 9, 'Porque o zelo por tua casa me devorou; e os insultos dos que te insultam caíram sobre mim;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 69, 10, 'Minha alma chorou e jejuou; porém [mais] insultos vieram sobre mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 69, 11, 'Vesti-me de saco, mas fui ridicularizado por eles num ditado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 69, 12, 'Os que se sentam à porta falam [mal] de mim; e os bebedores de álcool cantam [piadas] contra mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 69, 13, 'Mas eu oro a ti, SENHOR, [no] tempo aceitável. Pela grandeza de tua bondade, responde-me, ó Deus, pela fidelidade de tua salvação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 69, 14, 'Livra-me do lamaçal, e não me deixes afundar; seja eu resgatado dos que me odeiam, e das profundezas das águas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 69, 15, 'Não permitas que as correntes de águas me cubram, e que a profundeza não me devore, nem o poço feche sua boca sobre mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 69, 16, 'Responde-me, SENHOR; pois boa é tua bondade; olha para mim conforme tua piedade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 69, 17, 'E não escondas teu rosto de teu servo; porque estou angustiado; ouve-me depressa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 69, 18, 'Vem para perto de minha alma, [e] a liberta; resgata-me por causa de meus inimigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 69, 19, 'Tu conheces como me insultam, me envergonham e me humilham; diante de ti estão todos os meus adversários.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 69, 20, 'Insultos têm quebrado meu coração, e estou fraquíssimo; e esperei compaixão, porém [houve] nenhuma; [também esperei] por pessoas que me consolassem, mas não os achei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 69, 21, 'Deram-me fel como alimento; e em minha sede me deram vinagre para beber.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 69, 22, 'Torne-se a mesa diante deles como que um laço; e aquilo que [lhes] dá segurança [lhes] seja uma armadilha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 69, 23, 'Sejam escurecidos os olhos deles, para que não possam ver; e que seus quadris vacilem continuamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 69, 24, 'Derrama tua indignação sobre eles; e que sejam tomados pelo ardor de tua ira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 69, 25, 'A habitação deles seja desolada; e que não haja morador nas tendas deles;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 69, 26, 'Porque perseguem [aquele] a quem tu feriste, e contam histórias da dor daqueles a quem tu machucaste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 69, 27, 'Conta como maldade a maldade deles; e não sejam eles agraciados por tua justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 69, 28, 'Sejam riscados dos livro da vida; e não estejam eles escritos junto com os justos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 69, 29, 'Mas eu [estou] miserável e em dores; ó Deus, que tua salvação me proteja.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 69, 30, 'Louvarei o nome de Deus com cântico; e o engrandecerei com agradecimentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 69, 31, 'Isto agradará ao SENHOR mais do que [o sacrifício] de um boi [ou] de um bezerro com chifres e unhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 69, 32, 'Os mansos verão, e se alegrarão; vós que buscais a Deus, vosso coração viverá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 69, 33, 'Porque o SENHOR ouve aos necessitados, e não despreza os prisioneiros que lhe pertencem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 69, 34, 'Louvem a ele os céus, a terra, os mares, e tudo que neles se move;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 69, 35, 'Porque Deus salvará a Sião, e construirá as cidades de Judá; e habitarão ali, e a terão como posse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 69, 36, 'E a semente de seus servos a herdará; e os que amam o nome dele habitarão nela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 70, 1, 'Memorial de Davi, para o regente: Livra-me Deus; apressa-te para me socorrer, SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 70, 2, 'Envergonhem-se, e sejam confundidos os que procuram [matar] a minha alma; voltem-se para trás, e sejam humilhados os que gostam de me fazer o mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 70, 3, 'Virem-se para trás por causa de sua vergonha os que dizem: “Há, há!”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 70, 4, 'Alegrem-se e fiquem contentes em ti todos aqueles que te buscam; aqueles que amam tua salvação digam continuamente: Engrandecido seja Deus!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 70, 5, 'Eu, porém, estou miserável e necessitado; ó Deus, apressa-te a mim; tu [és] meu socorro e meu libertador; não demores, SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 71, 1, 'Em ti, SENHOR, confio; nunca me deixes ser envergonhado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 71, 2, 'Resgata-me e livra-me por tua justiça; inclina a mim teus ouvidos, e salva-me.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 71, 3, 'Sê tu minha rocha [e minha] habitação, para continuamente eu me abrigar nela; tu tens ordenado que eu seja salvo, porque tu [és] minha rocha forte e minha fortaleza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 71, 4, 'Meu Deus, livra-me da dominação do perverso, das mãos do injusto e cruel;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 71, 5, 'Pois tu és minha esperança, ó Senhor DEUS; [tu és] minha confiança desde minha juventude.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 71, 6, 'Tenho me apoiado em ti desde o ventre de minha mãe; das entranhas dela me tiraste; eu louvo continuamente a ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 71, 7, 'Para muitos fui como prodígio, porém tu és meu forte refúgio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 71, 8, 'Minha boca seja cheia de louvores a ti por tua glória o dia todo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 71, 9, 'Não me rejeites no tempo da velhice; não me desampares quando minha força se acabar;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 71, 10, 'Porque meus inimigos falam contra mim, e os que espiam minha alma tomam conselhos juntos uns com os outros;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 71, 11, 'Dizendo: Deus o desamparou; persegui, e o tomai, pois já não há quem o livre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 71, 12, 'Deus, não fiques longe de mim; Deus meu, apressa-te para me socorrer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 71, 13, 'Sejam envergonhados e pereçam os adversários de minha alma; cubram-se de humilhação e confusão aqueles que procuram [fazer] mal a mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 71, 14, 'Porém eu continuamente manterei a esperança, e darei todo o louvor a ti ainda mais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 71, 15, 'Minha boca contará tua justiça, [e] tua salvação o dia todo, ainda que eu não saiba sua medida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 71, 16, 'Irei adiante pelos poderes do Senhor DEUS; anunciarei tua justiça, que é somente tua.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 71, 17, 'Deus, tu tens me ensinado desde minha juventude; e até agora conto tuas maravilhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 71, 18, 'E agora, que estou velho e de cabelos grisalhos, não me desampares, Deus; enquanto eu não tiver anunciado a força de teu braço a [esta] geração, e teu poder a todos que vierem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 71, 19, 'E tua justiça, Senhor, [alcança] as alturas; porque tu tens feito grandes coisas. Quem é como tu, ó Deus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 71, 20, 'Tu, que me fizeste ver muitos males e aflições, voltarás a me dar vida; e voltarás a me tirar dos abismos da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 71, 21, 'Tu aumentarás minha honra e voltarás para me consolar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 71, 22, 'Eu também te louvarei com instrumento de cordas pela tua fidelidade, ó meu Deus; cantarei a ti com harpa, ó Santo de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 71, 23, 'Meus lábios terão muita alegria, porque cantarei a ti; e também [se alegrará] a minha alma, que tu tens resgatado.')
